#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=9

# Ticket #2. Projeto dev próprio do MAM, fora de organização, com o Bruno como
# Owner. Tudo o que criamos leva o prefixo mam- e, quando o recurso aceita, o
# rótulo app=mam.
REPO="RedeTVRevolution/mam-prk-redetv-"
P="${GCP_PROJECT_ID:-mam-redetv-dev-01}"
ACC="${GCP_ACCOUNT:-bruno.mosconi@gmail.com}"
REGION="us-east4"
SA_EMAIL="mam-terraform@${P}.iam.gserviceaccount.com"
BILLING_EXPECTED="015E16-E95BE6-00E37D"
GEMINI_RESULT="não testado"
BUDGET_STATUS="não conferido"
# Pendências que vão para o comentário da #2 e para o resumo final.
# Sem organização, o dev não aceita política de organização nem VPC-SC.
SKIPPED+=("E10 · Produção: ativar a política iam.disableServiceAccountKeyCreation (exige organização; o dev não tem)")
SKIPPED+=("E10 · Produção: criar o perímetro VPC Service Controls (exige organização; o dev não tem)")

cd "$(git rev-parse --show-toplevel)"

banner "GCP dev da RedeTV (ticket #2)"

# ── 1 ────────────────────────────────────────────────────────────────────
stage "Conta e projeto"
say "Fixo a conta $ACC e o projeto $P numa config gcloud só do MAM (mam-dev)."
[[ "$P" == *africa* ]] && { warn "O projeto africa-br nunca é usado no MAM. Abortando."; exit 1; }
if ! gcloud config configurations describe mam-dev >/dev/null 2>&1; then
  gcloud config configurations create mam-dev --no-activate >/dev/null
fi
# Só este script usa a config mam-dev; a config ativa do seu gcloud não muda.
export CLOUDSDK_ACTIVE_CONFIG_NAME=mam-dev
if ! gcloud auth list --format='value(account)' | grep -qx "$ACC"; then
  step "Vou abrir o login do Google. Entre com $ACC."
  gcloud auth login "$ACC"
fi
gcloud config set account "$ACC" >/dev/null 2>&1
gcloud config set project "$P" >/dev/null 2>&1
gcloud config set compute/region "$REGION" >/dev/null 2>&1
write_env GCP_PROJECT_ID "$P"
write_env GCP_REGION "$REGION"
# O estado do Terraform existe antes dele, então o nome nasce aqui, no .env.
write_env BUCKET_ESTADO_TF "$P-tfstate"
note "Para usar a mesma config no terminal: gcloud config configurations activate mam-dev"
pause "Enter para continuar"

# ── 2 ────────────────────────────────────────────────────────────────────
stage "Owner do projeto"
say "Confiro que $ACC é Owner de $P."
if [[ -z "$(gcloud projects get-iam-policy "$P" --flatten='bindings[].members' \
      --filter="bindings.role=roles/owner AND bindings.members=user:$ACC" \
      --format='value(bindings.role)' 2>/dev/null)" ]]; then
  warn "$ACC não aparece como Owner de $P. Confira o projeto e a conta e rode de novo."
  open_url "https://console.cloud.google.com/iam-admin/iam?project=$P"
  exit 1
fi
printf '  %s✓%s %s é Owner de %s\n' "$GREEN" "$RESET" "$ACC" "$P"
pause "Enter para continuar"

# ── 3 ────────────────────────────────────────────────────────────────────
stage "Conta de serviço do Terraform e impersonação"
say "Vou criar $SA_EMAIL, dar a ela os papéis que o Terraform usa"
say "(sem owner) e dar a você o direito de impersoná-la. Nenhuma chave é criada."
confirm "Aplicar essas mudanças no IAM do projeto?" || { warn "Nada foi alterado."; exit 1; }
gcloud services enable iam.googleapis.com iamcredentials.googleapis.com aiplatform.googleapis.com \
  billingbudgets.googleapis.com --project "$P"
if ! gcloud iam service-accounts describe "$SA_EMAIL" --project "$P" >/dev/null 2>&1; then
  gcloud iam service-accounts create mam-terraform --project "$P" \
    --display-name="MAM Terraform" --description="Aplica o Terraform do MAM (app=mam). Usada só por impersonação."
fi
# Sem owner, só o que o Terraform usa. projectIamAdmin entra porque Gemini,
# Firestore, logs e Eventarc só têm papéis no nível do projeto; o Terraform só
# usa google_project_iam_member e um audit config (ADR 0002). iam.workloadIdentityPoolAdmin e
# cloudbuild.builds.editor são do CD (#71): a federação com o GitHub e o envio
# ao Cloud Build.
# Papel dado à mão à mam-terraform entra aqui no mesmo dia.
PAPEIS_DA_TERRAFORM=(
  roles/resourcemanager.projectIamAdmin
  roles/serviceusage.serviceUsageAdmin
  roles/iam.serviceAccountAdmin
  roles/iam.serviceAccountUser
  roles/run.admin
  roles/storage.admin
  roles/artifactregistry.admin
  roles/datastore.owner
  roles/eventarc.admin
  roles/workflows.admin
  roles/identityplatform.admin
  roles/monitoring.editor
  roles/logging.configWriter
  roles/compute.networkAdmin # rede mam-validacao dos Jobs e apagar a rede default (#301)
  roles/iam.workloadIdentityPoolAdmin
  roles/cloudbuild.builds.editor
  roles/secretmanager.admin # apaga o segredo do SerpAPI que saiu do Terraform (#327); depois do publicar que o remove, o papel pode sair
  roles/cloudscheduler.admin # agendamento diário da purga da lixeira (#145)
  roles/bigquery.admin # dataset, tabelas e IAM no dataset do BigQuery (#260, #279, #280, #285)
  roles/cloudkms.admin # key ring, chave MAC do hash das chaves de API e IAM na chave (#272)
  roles/pubsub.admin # tópicos, assinaturas e fila de mensagens mortas (#273, #279)
  roles/compute.loadBalancerAdmin # balanceador HTTPS na frente do Cloud Run (#294)
  roles/certificatemanager.owner # certificado gerenciado, se o #294 usar o Certificate Manager
  roles/compute.securityAdmin # Cloud Armor (#295) e firewall da rede default (#301)
  roles/iam.roleAdmin # papel sob medida da Vertex (#302)
  roles/modelarmor.admin # cria o modelo do Model Armor da busca (#232)
)
for role in "${PAPEIS_DA_TERRAFORM[@]}"; do
  gcloud projects add-iam-policy-binding "$P" --member="serviceAccount:$SA_EMAIL" \
    --role="$role" --condition=None >/dev/null
  printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$role"
done
gcloud iam service-accounts add-iam-policy-binding "$SA_EMAIL" --project "$P" \
  --member="user:$ACC" --role=roles/iam.serviceAccountTokenCreator >/dev/null
say "Testando a impersonação (o IAM leva até um minuto para propagar)..."
ok=""
for _ in 1 2 3 4 5 6; do
  if gcloud auth print-access-token --impersonate-service-account="$SA_EMAIL" >/dev/null 2>&1; then ok=1; break; fi
  sleep 10
done
[[ -n "$ok" ]] || { warn "A impersonação ainda falha. Rode o wizard de novo em alguns minutos."; exit 1; }
printf '  %s✓%s você impersona %s\n' "$GREEN" "$RESET" "$SA_EMAIL"
# O Terraform impersona pelas credenciais padrão (ADC), não pelas do gcloud:
# testa esse caminho, porque um ADC antigo de outra conta passaria despercebido.
while :; do
  adc=$(gcloud auth application-default print-access-token 2>/dev/null || true)
  code=$(curl -sS -o /dev/null -w '%{http_code}' -X POST \
    -H "Authorization: Bearer $adc" -H "Content-Type: application/json" \
    "https://iamcredentials.googleapis.com/v1/projects/-/serviceAccounts/$SA_EMAIL:generateAccessToken" \
    -d '{"scope":["https://www.googleapis.com/auth/cloud-platform"]}' || true)
  [[ "$code" == 200 ]] && break
  warn "As credenciais padrão (ADC) não impersonam $SA_EMAIL (HTTP ${code:-000})."
  confirm "Abrir o login do ADC agora? Entre com $ACC." || { warn "Rode o wizard de novo depois."; exit 1; }
  gcloud auth application-default login
done
printf '  %s✓%s o Terraform consegue impersonar %s\n' "$GREEN" "$RESET" "$SA_EMAIL"
# O provider google do Terraform lê esta variável e impersona a conta.
write_env GOOGLE_IMPERSONATE_SERVICE_ACCOUNT "$SA_EMAIL"
pause "Enter para continuar"

# ── 4 ────────────────────────────────────────────────────────────────────
stage "Chamada de teste ao Gemini no endpoint global"
say "Uma chamada curta com a sua conta, com o rótulo app=mam (ADR 0001)."
while :; do
  ask GEMINI_MODEL "Modelo (vazio = gemini-3.5-flash-lite):" || true
  GEMINI_MODEL="${GEMINI_MODEL:-gemini-3.5-flash-lite}"
  token=$(gcloud auth print-access-token 2>/dev/null)
  out=$(mktemp)
  code=$(curl -sS -o "$out" -w '%{http_code}' -X POST \
    -H "Authorization: Bearer $token" -H "Content-Type: application/json" \
    "https://aiplatform.googleapis.com/v1/projects/$P/locations/global/publishers/google/models/$GEMINI_MODEL:generateContent" \
    -d '{"contents":[{"role":"user","parts":[{"text":"Responda apenas: ok"}]}],"labels":{"app":"mam"}}' || true)
  code="${code:-000}"
  if [[ "$code" == 200 ]]; then
    printf '  %s✓%s HTTP 200. Resposta: %s\n' "$GREEN" "$RESET" "$(grep -m1 '"text"' "$out" | sed 's/^ *//')"
    GEMINI_RESULT="ok: $GEMINI_MODEL respondeu HTTP 200 no endpoint global"
    rm -f "$out"; break
  fi
  warn "HTTP $code"; head -c 600 "$out"; printf '\n'; rm -f "$out"
  GEMINI_RESULT="falhou: HTTP $code com $GEMINI_MODEL"
  note "Se o modelo não existir, confira o id em https://cloud.google.com/vertex-ai/generative-ai/docs/models"
  confirm "Tentar de novo (pode trocar o modelo)?" || { SKIPPED+=("Chamada de teste ao Gemini no endpoint global ($GEMINI_RESULT)"); break; }
  GEMINI_MODEL=""
done
write_env GEMINI_MODEL "$GEMINI_MODEL"
write_env GEMINI_LOCATION "global"
pause "Enter para continuar"

# ── 5 ────────────────────────────────────────────────────────────────────
stage "Faturamento"
BILLING=$(gcloud billing projects describe "$P" --format='value(billingAccountName)')
BILLING="${BILLING#billingAccounts/}"
BILLING_ON=$(gcloud billing projects describe "$P" --format='value(billingEnabled)')
write_env GCP_BILLING_ACCOUNT "$BILLING"
if [[ "$BILLING" == "$BILLING_EXPECTED" && "$BILLING_ON" == True ]]; then
  printf '  %s✓%s faturamento ativo na conta %s\n' "$GREEN" "$RESET" "$BILLING"
else
  warn "Faturamento: conta '${BILLING:-nenhuma}', ativo=${BILLING_ON:-?}; esperado $BILLING_EXPECTED ativo."
  open_url "https://console.cloud.google.com/billing/linkedaccount?project=$P"
  SKIPPED+=("Ligar $P à conta de faturamento $BILLING_EXPECTED")
fi
pause "Enter para continuar"

# ── 6 ────────────────────────────────────────────────────────────────────
stage "Alerta de orçamento do projeto"
say "Precisa de quem administra a conta de faturamento $BILLING; se não for"
say "você, repasse estes passos a essa pessoa."
open_url "https://console.cloud.google.com/billing/$BILLING/budgets"
step "Criar orçamento → Nome: mam-dev"
step "Escopo: Projetos = só $P (sem filtro de rótulo)"
step "Valor: especificado, mensal, no valor combinado"
step "Ações: limites em 50%, 90% e 100% do valor"
step "Notificações: e-mail aos administradores de faturamento e, se quiser outro"
step "destinatário, vincule um canal de e-mail do Cloud Monitoring → Concluir"
note "O orçamento soma o projeto inteiro."
ask BUDGET_AMOUNT "Valor mensal do orçamento (ex.: US\$ 100):" || true
ask BUDGET_RECIPIENT "Destinatário(s) do alerta (e-mail):" || true
write_env BUDGET_AMOUNT "${BUDGET_AMOUNT:-}"
write_env BUDGET_RECIPIENT "${BUDGET_RECIPIENT:-}"
# Só conta como criado se o gcloud enxergar o orçamento. Sem acesso à conta de
# faturamento a consulta falha, e o orçamento fica como pendência.
pause "Enter quando o orçamento estiver criado (ou para deixar pendente)"
if [[ -n "$(gcloud billing budgets list --billing-account="$BILLING" \
      --filter='displayName=mam-dev' --format='value(name)' 2>/dev/null)" ]]; then
  BUDGET_STATUS="criado: ${BUDGET_AMOUNT:-?}/mês para o projeto inteiro, alerta para ${BUDGET_RECIPIENT:-?}"
  printf '  %s✓%s orçamento mam-dev encontrado na conta %s\n' "$GREEN" "$RESET" "$BILLING"
else
  BUDGET_STATUS="pendente (não confirmado pelo gcloud)"
  warn "Não consegui ver o orçamento mam-dev na conta $BILLING; fica como pendência."
  SKIPPED+=("Criar o orçamento mam-dev de ${BUDGET_AMOUNT:-valor a combinar}/mês, só para o projeto $P, na conta de faturamento $BILLING (precisa de quem administra essa conta)")
fi

# ── 7 ────────────────────────────────────────────────────────────────────
stage "Identity Platform"
# Inicializar o Identity Platform exige firebase.projects.update, que nenhum papel
# do Identity Platform dá à mam-terraform. Então você, como Owner, inicializa uma
# vez (só cria a config vazia), e o Terraform importa a config e cuida do resto (#11).
gcloud services enable identitytoolkit.googleapis.com --project "$P"
IDP_TOKEN=$(gcloud auth print-access-token)
idp() {
  curl -sS -o /dev/null -w '%{http_code}' -H "Authorization: Bearer $IDP_TOKEN" \
    -H "x-goog-user-project: $P" "$@" || true
}
if [[ "$(idp "https://identitytoolkit.googleapis.com/admin/v2/projects/$P/config")" == 200 ]]; then
  printf '  %s✓%s Identity Platform já inicializado em %s\n' "$GREEN" "$RESET" "$P"
elif [[ "$(idp -X POST -d '' "https://identitytoolkit.googleapis.com/v2/projects/$P/identityPlatform:initializeAuth")" == 200 ]]; then
  printf '  %s✓%s Identity Platform inicializado em %s\n' "$GREEN" "$RESET" "$P"
else
  warn "Não consegui inicializar o Identity Platform em $P."
  SKIPPED+=("Inicializar o Identity Platform em $P como Owner (etapa 7 do wizard), antes do make deploy-dev")
fi
pause "Enter para continuar"

# ── 8 ────────────────────────────────────────────────────────────────────
# ENSAIO_FALHAS_INICIO (o teste api/tests/test_wizard_ensaio_de_alerta.py roda este bloco)
stage "Ensaio do alerta de falhas por etapa com uma condição só (#337, para a #330)"
say "A API de alertas não tem validateOnly e o agente não cria recursos, então crio"
say "uma política descartável, desabilitada e sem canal de notificação, só para ver"
say "se a API aceita uma condição que soma o Job e o Workflows. Apago no fim."
PREFIXO_ENSAIO="mam-ensaio-"

# ensaiar_alerta cria as políticas descartáveis, mostra a aceita e apaga tudo.
ensaiar_alerta() {
  ENSAIO_DIR=$(mktemp -d)
  ENSAIO_CRIADAS=()
  ENSAIO_ACEITA=""
  ENSAIO_GRAVADA=""

  # Apaga o que o ensaio criou e tudo o que tiver o prefixo, de um ensaio anterior
  # interrompido; roda no trap, então não pode falhar no meio.
  limpar_ensaio() {
    local nome
    for nome in ${ENSAIO_CRIADAS[@]+"${ENSAIO_CRIADAS[@]}"}; do
      gcloud alpha monitoring policies delete "$nome" --project "$P" --quiet >/dev/null 2>&1 || true
    done
    while read -r nome; do
      [[ -n "$nome" ]] || continue
      gcloud alpha monitoring policies delete "$nome" --project "$P" --quiet >/dev/null 2>&1 || true
    done < <(gcloud alpha monitoring policies list --project "$P" \
      --filter="displayName~^${PREFIXO_ENSAIO}" --format='value(name)' 2>/dev/null || true)
    rm -rf "$ENSAIO_DIR"
  }
  trap limpar_ensaio EXIT

  # politica_do_ensaio FORMA escreve o JSON da política descartável da forma a ou b.
  politica_do_ensaio() {
    local forma="$1" arquivo="$ENSAIO_DIR/politica-$1.json" condicao
    if [[ "$forma" == a ]]; then
      condicao=$(printf '"conditionThreshold":{"filter":"metric.type=\\"logging.googleapis.com/user/%s\\" AND resource.type = one_of(\\"cloud_run_job\\", \\"workflows.googleapis.com/Workflow\\")","comparison":"COMPARISON_GT","thresholdValue":%s,"duration":"0s","aggregations":[{"alignmentPeriod":"%s","perSeriesAligner":"ALIGN_DELTA","crossSeriesReducer":"REDUCE_SUM","groupByFields":["metric.label.etapa"]}]}' \
        "$METRICA" "$LIMITE" "$JANELA")
    else
      condicao=$(printf '"conditionPrometheusQueryLanguage":{"query":"sum by (etapa) (increase(logging_googleapis_com:user_%s{monitored_resource=~\\"cloud_run_job|workflows.googleapis.com/Workflow\\"}[%s])) > %s","duration":"0s","evaluationInterval":"60s"}' \
        "$METRICA" "$JANELA" "$LIMITE")
    fi
    printf '{"displayName":"%sfalhas-por-etapa-%s","combiner":"OR","enabled":false,"notificationChannels":[],"conditions":[{"displayName":"Ensaio das falhas por etapa (%s)",%s}]}\n' \
      "$PREFIXO_ENSAIO" "$forma" "$forma" "$condicao" > "$arquivo"
    printf '%s' "$arquivo"
  }

  for forma in a b; do
    arquivo=$(politica_do_ensaio "$forma")
    say "Forma ($forma): criando ${PREFIXO_ENSAIO}falhas-por-etapa-$forma..."
    if nome=$(gcloud alpha monitoring policies create --project "$P" \
          --policy-from-file="$arquivo" --format='value(name)' 2>"$ENSAIO_DIR/erro-$forma.txt"); then
      ENSAIO_CRIADAS+=("$nome")
      ENSAIO_ACEITA="$forma"
      ENSAIO_GRAVADA=$(gcloud alpha monitoring policies describe "$nome" --project "$P" --format=json) \
        || ENSAIO_GRAVADA="(o describe falhou; a API aceitou este pedido) $(cat "$arquivo")"
      printf '  %s✓%s a API aceitou a forma (%s)\n' "$GREEN" "$RESET" "$forma"
      break
    fi
    warn "A API recusou a forma ($forma):"
    sed 's/^/    /' "$ENSAIO_DIR/erro-$forma.txt"
  done

  limpar_ensaio
  trap - EXIT
  if ! RESTANTES=$(gcloud alpha monitoring policies list --project "$P" \
      --filter="displayName~^${PREFIXO_ENSAIO}" --format='value(name)'); then
    warn "Não consegui listar as políticas para conferir a limpeza."
    SKIPPED+=("Conferir que não sobrou política $PREFIXO_ENSAIO* do ensaio (#337) em $P")
  elif [[ -z "$RESTANTES" ]]; then
    printf '  %s✓%s nenhuma política %s* sobrou\n' "$GREEN" "$RESET" "$PREFIXO_ENSAIO"
  else
    warn "Sobrou política do ensaio; apague à mão:"
    printf '%s\n' "$RESTANTES" | sed 's/^/    /'
    SKIPPED+=("Apagar as políticas $PREFIXO_ENSAIO* que sobraram do ensaio (#337) em $P")
  fi

  if [[ -n "$ENSAIO_ACEITA" ]]; then
    say "Copie para um comentário na #330: a API aceitou a forma ($ENSAIO_ACEITA) e gravou assim:"
    printf '\n'; printf '%s\n' "$ENSAIO_GRAVADA" | sed 's/^/    /'; printf '\n'
  else
    warn "A API recusou as duas formas. Copie os dois erros acima para a #330."
    SKIPPED+=("Comentar na #330 que a API recusou as formas (a) e (b) do alerta de falhas por etapa (#337)")
  fi
}

# Antes do primeiro deploy (ou de um deploy com estas saídas) o Terraform não as tem.
if ! { METRICA=$(terraform -chdir=infra output -raw metrica_de_falhas_por_etapa) \
    && JANELA=$(terraform -chdir=infra output -raw janela_dos_alertas_s) \
    && LIMITE=$(terraform -chdir=infra output -raw limite_de_falhas_por_etapa); } 2>/dev/null; then
  warn "O estado do Terraform ainda não tem a métrica, a janela e o limite do alerta; rode o make deploy-dev e esta etapa de novo."
  SKIPPED+=("Ensaio do alerta de falhas por etapa (#337): rodar a etapa 8 depois do make deploy-dev e comentar na #330")
elif ! confirm "Criar (e apagar em seguida) as políticas descartáveis $PREFIXO_ENSAIO* em $P?"; then
  warn "Nada foi criado."
  SKIPPED+=("Ensaio do alerta de falhas por etapa (#337): rodar a etapa 8 e comentar na #330")
else
  ensaiar_alerta
fi
# ENSAIO_FALHAS_FIM
pause "Enter para continuar"

# ── 9 ────────────────────────────────────────────────────────────────────
stage "Registrar na issue #2"
body=$(mktemp)
{
  printf '## Projeto GCP dev (registrado pelo wizard)\n\n'
  printf -- '- Projeto: `%s`, fora de organização, com `%s` como Owner\n' "$P" "$ACC"
  printf -- '- Faturamento: `%s`\n' "$BILLING"
  printf -- '- Terraform por impersonação de `%s`, sem chave em arquivo e sem owner (ADR 0002)\n' "$SA_EMAIL"
  printf -- '- Gemini: %s\n' "$GEMINI_RESULT"
  printf -- '- Orçamento: %s\n' "$BUDGET_STATUS"
  printf -- '- Recursos do MAM levam o prefixo `mam-` e o rótulo `app=mam`\n\n'
  printf '### Pendências\n\n'
  for s in "${SKIPPED[@]}"; do printf -- '- [ ] %s\n' "$s"; done
} > "$body"
say "Comentário que vai para a #2:"; printf '\n'; sed 's/^/    /' "$body"; printf '\n'
if confirm "Publicar este comentário na issue #2?"; then
  gh issue comment 2 --repo "$REPO" --body-file "$body" >/dev/null
  printf '  %s✓%s comentário publicado na #2\n' "$GREEN" "$RESET"
else
  SKIPPED+=("Publicar o resumo na #2: gh issue comment 2 --repo $REPO")
fi
rm -f "$body"
pause "Enter para ver o resumo"

finish
}

run_wizard "$@"; exit
